  let timerId = null;

  const debounced = function (...args) {
    const context = this;

    // Leading edge: fire immediately if first call in this "burst"
    const callNow = leading && timerId === null;

    clearTimeout(timerId);

    timerId = setTimeout(() => {
      timerId = null;
      // Trailing edge: fire after delay has passed
